      SUBROUTINE MR3R2V(N)CC     MULTIPLIES RC2 AND R2V AND STORES RESULT IN R2VC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'R2VT.CIN'      INCLUDE 'RC2.CIN'      INCLUDE 'RC3.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'T2VT.CIN'      INCLUDE 'TC2.CIN'      INCLUDE 'TC3.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'U2VT.CIN'      INCLUDE 'UC2.CIN'      INCLUDE 'UC3.CIN'      INCLUDE 'US.CIN'CC---------------------------------------------------------------------      DO 10 JK = 1, 36   10 R2VTL(JK) = R2VL(JK,N)      IF (NORD2 .GE. 2) THEN        DO 20 JKL = 1, 105        T2VTL(JKL) = T2VL(JKL,N)   20   CONTINUE      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 JKL = 1, 280        U2VTL(JKL) = U2VL(JKL,N)   30   CONTINUE      ENDIFC      IF (NORD2 .EQ. 1) THEN        CALL CAB(RS,RC3,R2VT)      ELSE IF (NORD2 .EQ. 2) THEN        CALL CABD2(RS,TS,RC3,TC3,RC2,R2VT,T2VT)      ELSE IF (NORD2 .EQ. 3) THEN        CALL CABD3(RS,TS,US,RC3,TC3,UC3,RC2,TC2,     >             R2VT,T2VT,U2VT)      ENDIFC      DO 50 JK = 1, 36   50 R2VL(JK,N) = RSL(JK)      IF (NORD2 .GE. 2) THEN        DO 60 JKM = 1, 105   60   T2VL(JKM,N) = TSL(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 70 JKLM = 1, 280   70   U2VL(JKLM,N) = USL(JKLM)      ENDIFC      RETURN      END